/* ===== 番茄小说 PUA 字体反混淆库 =====
 * 网页端正文/榜单文本会把常用字替换成 Unicode 私用区码位(U+E3E8~U+E55B)，
 * 真实字形由 awesome-font 字体承载。此映射表已由字体逐字还原核对，
 * 覆盖 0xE3E8 起 362 个码位，实测整本还原率 100%。
 */
var FQM = "D在主特家军然表场4要只v和?6别还g现儿岁??此象月3出战工相o男直失世F都平文什VO将真T那当?会立些u是十张学气大爱两命全后东性通被1它乐接而感车山公了常以何可话先pi叫轻M士w着变尔快l个说少色里安花远7难师放t报认面道S?克地度I好机U民写把万同水新没书电吃像斯5为y白几日教看但第加候作上拉住有法r事应位利你声身国问马女他Y比父xAHNsX边美对所金活回意到z从j知又内因点Q三定8Rb正或夫向德听更?得告并本q过记L让打f人就者去原满体做经K走如孩cG给使物?最笑部?员等受k行一条果动光门头见往自解成处天能于名其发总母的死手入路进心来h时力多开已许d至由很界n小与Z想代么分生口再妈望次西风种带J?实情才这?E我神格长觉间年眼无不亲关结0友信下却重己老2音字m呢明之前高PB目太e9起稜她也W用方子英每理便四数期中C外样a海们任";
var FQB = 0xE3E8;

/* 还原 PUA 密文 */
function fqD(t) {
    t = String(t == null ? "" : t);
    var o = "", i, c, k;
    for (i = 0; i < t.length; i++) {
        c = t.charCodeAt(i);
        k = c - FQB;
        if (k >= 0 && k < FQM.length) { o += FQM.charAt(k); } else { o += t.charAt(i); }
    }
    return o;
}

/* 安全取值: fqG(o,'a') 等价于 o&&o.a,取不到返回 "" */
function fqG(o, k) {
    if (o === undefined || o === null) { return ""; }
    var v = o[k];
    if (v === undefined || v === null) { return ""; }
    return v;
}

/* 时间戳(秒) -> yyyy-MM-dd */
function fqDate(v) {
    v = Number(v);
    if (!v || isNaN(v)) { return ""; }
    var d = new Date(v * 1000);
    var m = d.getMonth() + 1, dd = d.getDate();
    return d.getFullYear() + "-" + (m < 10 ? "0" + m : m) + "-" + (dd < 10 ? "0" + dd : dd);
}

/* 依次取第一个非空字段 */
function fqP(o, ks) {
    var i, v;
    for (i = 0; i < ks.length; i++) {
        v = o[ks[i]];
        if (v !== undefined && v !== null && v !== "") { return v; }
    }
    return "";
}

/* 从页面 HTML 里提取 window.__INITIAL_STATE__ 并解析为对象
 * 该 JSON 含非法字面量 undefined,先替换为 null 再解析
 */
function fqS(h) {
    h = String(h == null ? "" : h);
    var i = h.indexOf("window.__INITIAL_STATE__");
    if (i < 0) { return null; }
    var j = h.indexOf("{", i);
    if (j < 0) { return null; }
    var d = 0, ins = false, esc = false, q = "", k, e = -1, c;
    for (k = j; k < h.length; k++) {
        c = h.charAt(k);
        if (ins) {
            if (esc) { esc = false; }
            else if (c === "\\") { esc = true; }
            else if (c === q) { ins = false; }
        } else {
            if (c === '"' || c === "'") { ins = true; q = c; }
            else if (c === "{") { d++; }
            else if (c === "}") { d--; if (d === 0) { e = k; break; } }
        }
    }
    if (e < 0) { return null; }
    var s = h.substring(j, e + 1).replace(/([:,\[])\s*undefined\s*([,}\]])/g, "$1null$2");
    try { return JSON.parse(s); } catch (err) { return null; }
}

/* 从各种榜单/搜索响应里取出书籍数组 */
function fqL(o) {
    var d = fqG(o, "data");
    if (d === "") { d = o; }
    var cand = [fqG(d, "search_book_data_list"), fqG(d, "book_list"),
                fqG(d, "list"), fqG(d, "data"), fqG(o, "book_list")];
    var i;
    for (i = 0; i < cand.length; i++) {
        if (cand[i] !== "" && cand[i] !== null && cand[i].length) { return cand[i]; }
    }
    return [];
}

/* 归一化一本书 -> 统一 JSON 串 */
function fqB(b) {
    return JSON.stringify({
        n: fqD(fqP(b, ["book_name", "bookName"])),
        a: fqD(fqP(b, ["author"])),
        k: fqD(fqP(b, ["category"])),
        i: fqD(fqP(b, ["book_abstract", "abstract"])),
        w: fqP(b, ["word_count", "wordNumber"]),
        l: fqD(fqP(b, ["last_chapter_title", "lastChapterTitle", "title"])),
        t: fqDate(fqP(b, ["last_chapter_time", "lastChapterUpdateTime"])),
        c: fqP(b, ["thumb_url", "thumbUri"]),
        u: "https://fanqienovel.com/page/" + fqP(b, ["book_id", "bookId"])
    });
}

/* 列表规则: 同时兼容 JSON 接口与 SSR 页面 */
function fqParse(result) {
    var s = String(result == null ? "" : result).replace(/^\s+/, "");
    var L = null, o;
    if (s.charAt(0) === "{") {
        try { o = JSON.parse(s); } catch (e) { o = null; }
        if (o !== null) { L = fqL(o); }
    }
    if (L === null) {
        var st = fqS(s);
        if (st !== null) { L = fqG(fqG(st, "rank"), "book_list"); if (L === "") { L = null; } }
    }
    return L;
}

function fqBookList(result) {
    var L = fqParse(result);
    if (L === null) { return []; }
    var out = [], i;
    for (i = 0; i < L.length; i++) { out.push(fqB(L[i])); }
    return out;
}

/* 发现页: 榜单接口偶发返回空列表,自动重试 */
function fqExplore(result) {
    var out = fqBookList(result);
    if (out.length > 0) { return out; }
    if (typeof baseUrl === "undefined" || baseUrl === null) { return out; }
    var u = String(baseUrl);
    if (u.indexOf("fanqienovel.com/api/") < 0) { return out; }
    var i, r;
    for (i = 0; i < 3; i++) {
        r = "";
        try { r = String(java.ajax(u)); } catch (e) { r = ""; }
        if (r !== "") {
            out = fqBookList(r);
            if (out.length > 0) { return out; }
        }
    }
    return out;
}

/* ===== 分类榜单分页 =====
 * 榜单接口 limit 上限 100；offset 可继续翻页，单分类实测约 313 本(4 页)。
 * 「频道全部」入口把 页码 映射为 (分类, 偏移)：每 4 页对应一个分类。
 */
var FQ_MALE = [1141, 1140, 8, 261, 124, 1014, 273, 27, 263, 258, 272, 539, 262, 257, 751, 504, 746, 718, 1016];
var FQ_FEMALE = [1139, 8, 746, 1015, 248, 23, 79, 267, 246, 539, 253, 24, 749, 745, 747, 750, 748, 1017];
var FQ_PAGE_PER_CAT = 4;   /* 每个分类取 4 页 = 400 本上限 */

function fqCatId(page, gender) {
    var ids = (Number(gender) === 0) ? FQ_FEMALE : FQ_MALE;
    var i = Math.floor((Number(page) - 1) / FQ_PAGE_PER_CAT);
    if (!(i >= 0)) { i = 0; }
    if (i >= ids.length) { i = ids.length - 1; }
    return ids[i];
}

function fqCatOff(page) {
    var k = (Number(page) - 1) % FQ_PAGE_PER_CAT;
    if (!(k >= 0)) { k = 0; }
    return k * 100;
}

/* 频道一共能翻多少页(仅用于说明,不影响功能) */
function fqCatTotalPage(gender) {
    var ids = (Number(gender) === 0) ? FQ_FEMALE : FQ_MALE;
    return ids.length * FQ_PAGE_PER_CAT;
}

