ruleBookInfo.kind:
@js:(function(){
  var p = JSON.parse(String(result));
  var out = [];
  try {
    var a = JSON.parse(String(fqG(p, "categoryV2")));
    for (var i = 0; i < a.length; i++) { out.push(fqD(String(fqG(a[i], "Name")))); }
  } catch (e) {}
  if (out.length === 0) {
    var c = fqD(String(fqG(p, "category")));
    if (c !== "") { out.push(c); }
  }
  return out.join(",");
})()

