ruleContent.content:
@js:(function(){
  var st = fqS(String(result));
  var cd = fqG(fqG(st, "reader"), "chapterData");
  var c = fqD(String(fqG(cd, "content")));
  var imgs = [];
  c = c.replace(/<img[^>]*?(\{[^{}]*"web_uri"[^{}]*\})[^>]*>/gi, function (m, js) {
    var o = null;
    try { o = JSON.parse(js); } catch (e) { return ""; }
    var uri = fqG(o, "web_uri");
    if (uri === "") { return ""; }
    imgs.push("https://p6-novel.byteimg.com/" + uri + "~tplv-resize:" +
              fqG(o, "width") + ":" + fqG(o, "height") + ".image");
    return "\u0001" + (imgs.length - 1) + "\u0001";
  });
  c = c.replace(/<\/p>\s*<p>/gi, "\n");
  c = c.replace(/<br\s*\/?>/gi, "\n");
  c = c.replace(/<\/?p[^>]*>/gi, "\n");
  c = c.replace(/<\/img>/gi, "");
  c = c.replace(/<[^>]+>/g, "");
  c = c.replace(/&nbsp;/g, " ");
  c = c.replace(/&lt;/g, "<");
  c = c.replace(/&gt;/g, ">");
  c = c.replace(/&quot;/g, '"');
  c = c.replace(/&#39;/g, "'");
  c = c.replace(/&amp;/g, "&");
  c = c.replace(/\r/g, "");
  c = c.replace(/[ \t]+\n/g, "\n");
  c = c.replace(/\n{3,}/g, "\n\n");
  c = c.replace(/\u0001(\d+)\u0001/g, function (m, i) {
    return "\n<img src=\"" + imgs[Number(i)] + "\">\n";
  });
  return c.replace(/^\s+|\s+$/g, "");
})()

